const start = $('Start Resumable Upload').item.json;
const location = start.headers?.location || start.headers?.Location;
if (!location) throw new Error('YouTube did not return a resumable upload URL');
const token = $('Resolve YouTube Token').item.json.access_token;
const mimeType = $input.item.binary?.data?.mimeType || 'video/mp4';
const video = await this.helpers.getBinaryDataBuffer(0, 'data');
const uploaded = await this.helpers.httpRequest({ method: 'PUT', url: location, headers: { Authorization: 'Bearer ' + token, 'Content-Type': mimeType }, body: video, json: true, timeout: 3600000 });
return { json: uploaded };
